-- Phase 2: order workflow history and private product cost / stock-alert settings.
-- Cost and packaging data is intentionally stored outside public.products because public products are readable by storefront visitors.
alter table public.orders add column if not exists cancellation_reason text;
create table if not exists public.order_status_history (
 id bigint generated by default as identity primary key,
 order_id uuid not null references public.orders(id) on delete cascade,
 from_status text check (from_status is null or from_status in ('pending','processing','shipped','delivered','cancelled')),
 to_status text not null check (to_status in ('pending','processing','shipped','delivered','cancelled')),
 reason text not null default '',
 changed_by text not null default lower(coalesce(auth.jwt() ->> 'email','')),
 changed_at timestamptz not null default now()
);
create index if not exists order_status_history_order_changed_idx on public.order_status_history(order_id,changed_at desc);
alter table public.order_status_history enable row level security;
grant select,insert on public.order_status_history to authenticated;
grant usage,select on sequence public.order_status_history_id_seq to authenticated;
drop policy if exists "Admins can read order status history with MFA" on public.order_status_history;
create policy "Admins can read order status history with MFA" on public.order_status_history for select to authenticated using (lower(coalesce((select auth.jwt()->>'email'),''))='halalfoodbd.official@gmail.com' and coalesce((select auth.jwt()->>'aal'),'aal1')='aal2');
drop policy if exists "Admins can insert order status history with MFA" on public.order_status_history;
create policy "Admins can insert order status history with MFA" on public.order_status_history for insert to authenticated with check (lower(coalesce((select auth.jwt()->>'email'),''))='halalfoodbd.official@gmail.com' and coalesce((select auth.jwt()->>'aal'),'aal1')='aal2' and lower(coalesce(changed_by,''))=lower(coalesce((select auth.jwt()->>'email'),'')));
create or replace function public.admin_update_order_status(p_order_id uuid,p_next_status text,p_cancellation_reason text default null)
returns table(order_id uuid,order_number text,old_status text,new_status text,cancellation_reason text,updated_at timestamptz)
language plpgsql set search_path=''
as $$
declare
 v_email text:=lower(coalesce(auth.jwt()->>'email',''));
 v_aal text:=coalesce(auth.jwt()->>'aal','aal1');
 v_next_status text:=lower(trim(coalesce(p_next_status,'')));
 v_old_status text; v_order_number text; v_updated_at timestamptz; v_saved_reason text; v_reason text;
begin
 if v_email<>'halalfoodbd.official@gmail.com' or v_aal<>'aal2' then raise exception 'Admin access with completed MFA is required.' using errcode='42501'; end if;
 if v_next_status not in ('pending','processing','shipped','delivered','cancelled') then raise exception 'Unsupported order status.' using errcode='22023'; end if;
 if v_next_status='cancelled' then
  v_reason:=trim(coalesce(p_cancellation_reason,''));
  if length(v_reason)<3 then raise exception 'Enter a cancellation reason of at least 3 characters.' using errcode='22023'; end if;
  if length(v_reason)>500 then raise exception 'Cancellation reason must be 500 characters or fewer.' using errcode='22023'; end if;
 else v_reason:=null; end if;
 select o.status,o.order_number into v_old_status,v_order_number from public.orders o where o.id=p_order_id for update;
 if not found then raise exception 'Order not found.' using errcode='P0002'; end if;
 if v_old_status=v_next_status then raise exception 'Order already has that status.' using errcode='22023'; end if;
 update public.orders o set status=v_next_status,cancellation_reason=case when v_next_status='cancelled' then v_reason else o.cancellation_reason end,updated_at=now()
 where o.id=p_order_id returning o.cancellation_reason,o.updated_at into v_saved_reason,v_updated_at;
 insert into public.order_status_history(order_id,from_status,to_status,reason,changed_by)
 values(p_order_id,v_old_status,v_next_status,case when v_next_status='cancelled' then v_reason else 'Status updated from the admin panel.' end,v_email);
 return query select p_order_id,v_order_number,v_old_status,v_next_status,v_saved_reason,v_updated_at;
end;
$$;
revoke all on function public.admin_update_order_status(uuid,text,text) from public;
revoke all on function public.admin_update_order_status(uuid,text,text) from anon;
grant execute on function public.admin_update_order_status(uuid,text,text) to authenticated;
create table if not exists public.admin_product_costs (
 product_id uuid primary key references public.products(id) on delete cascade,
 cost_price numeric(12,2) check(cost_price is null or cost_price>=0),
 packaging_cost numeric(12,2) not null default 0 check(packaging_cost>=0),
 low_stock_threshold numeric(12,3) not null default 5 check(low_stock_threshold>=0),
 updated_by text not null default lower(coalesce(auth.jwt()->>'email','')),
 updated_at timestamptz not null default now()
);
alter table public.admin_product_costs enable row level security;
grant select,insert,update on public.admin_product_costs to authenticated;
drop policy if exists "Admin can read product cost settings with MFA" on public.admin_product_costs;
create policy "Admin can read product cost settings with MFA" on public.admin_product_costs for select to authenticated using (lower(coalesce((select auth.jwt()->>'email'),''))='halalfoodbd.official@gmail.com' and coalesce((select auth.jwt()->>'aal'),'aal1')='aal2');
drop policy if exists "Admin can insert product cost settings with MFA" on public.admin_product_costs;
create policy "Admin can insert product cost settings with MFA" on public.admin_product_costs for insert to authenticated with check (lower(coalesce((select auth.jwt()->>'email'),''))='halalfoodbd.official@gmail.com' and coalesce((select auth.jwt()->>'aal'),'aal1')='aal2' and lower(coalesce(updated_by,''))=lower(coalesce((select auth.jwt()->>'email'),'')));
drop policy if exists "Admin can update product cost settings with MFA" on public.admin_product_costs;
create policy "Admin can update product cost settings with MFA" on public.admin_product_costs for update to authenticated using (lower(coalesce((select auth.jwt()->>'email'),''))='halalfoodbd.official@gmail.com' and coalesce((select auth.jwt()->>'aal'),'aal1')='aal2') with check (lower(coalesce((select auth.jwt()->>'email'),''))='halalfoodbd.official@gmail.com' and coalesce((select auth.jwt()->>'aal'),'aal1')='aal2' and lower(coalesce(updated_by,''))=lower(coalesce((select auth.jwt()->>'email'),'')));
comment on table public.admin_product_costs is 'Private admin-only cost and low-stock settings, separated from the public product catalog.';
comment on table public.order_status_history is 'Admin-only order status changes from feature enablement onward; earlier transitions were not backfilled.';
